const MCC_VERSION='2026.08.16-maint-cost1';
function mccDecorate(){const form=document.getElementById('maintenanceCompleteForm');if(!form||form.dataset.mcc===MCC_VERSION)return;const cost=form.elements.cost_amount;if(!(cost instanceof HTMLInputElement))return;form.dataset.mcc=MCC_VERSION;cost.min='0';cost.inputMode='decimal';const field=cost.closest('.field');const label=field?.querySelector('label');if(label)label.innerHTML='Стоимость, ₽ <span class="muted">(если известна)</span>';if(field&&!field.querySelector('[data-mcc-hint]')){const hint=document.createElement('div');hint.className='hint';hint.dataset.mccHint='1';hint.textContent='Оставьте пустым, если стоимость неизвестна. Укажите 0 только если ТО действительно выполнено без затрат.';field.appendChild(hint)}}
let mccQueued=false;function mccSchedule(){if(mccQueued)return;mccQueued=true;queueMicrotask(()=>{mccQueued=false;mccDecorate()})}new MutationObserver(mccSchedule).observe(document.documentElement,{childList:true,subtree:true});window.addEventListener('fleet:role-ux-ready',mccSchedule);mccSchedule();
